// ===== DỮ LIỆU CỦA HLV SỨC KHỎE =====
// Tư thế 3D: đơn vị độ. P=nghiêng thân (+ cúi về trước), R=lăn ngang, sp=gập cột sống, nf=gập cổ
// Hai bên: l/r + hf (gập hông), ha (dạng hông), kf (gập gối), af (cổ chân, + mũi chân xuống; bỏ trống = bàn chân phẳng),
// sf (đưa tay ra trước/lên), sa (dang tay ngang), sy (xoay tay ra trước), ef (gập khuỷu)
const S = (o = {}, extra = {}) => {
  const r = {};
  for (const [k, v] of Object.entries(o)) {
    if (['P', 'R', 'Y', 'sp', 'nf', 'tw'].includes(k)) r[k] = v; else { r['l' + k] = v; r['r' + k] = v; }
  }
  return Object.assign(r, extra);
};
const N = S({ sa: 8 });

